 const visible=data.posts.filter(p=>(!formatFilterActive||p.format===publicationType)&&!dateRangeInvalid&&(!dateFrom||p.date.slice(0,10)>=dateFrom)&&(!dateTo||p.date.slice(0,10)<=dateTo)&&(filter==='all'||p.client_id===filter)&&(channel==='all'||p.channel===channel)&&(['Aprobaciones','Comentarios'].includes(view)||stateFilter==='all'||p.status===stateFilter)&&(`${p.title} ${p.copy} ${client(p.client_id)?.name}`.toLowerCase().includes(query.toLowerCase())));
 const monthPosts=visible.filter(p=>p.date.slice(0,7)===stamp(month).slice(0,7));

