 const start=mode==='Semana'?new Date(month.getFullYear(),month.getMonth(),month.getDate()-(month.getDay()+6)%7):new Date(month.getFullYear(),month.getMonth(),1-offset);
 const weekCount=mode==='Semana'?7:Math.ceil((offset+new Date(month.getFullYear(),month.getMonth()+1,0).getDate())/7)*7;
