 const periodPosts=(dateFrom||dateTo)?visible:view==='Calendario'?(mode==='Semana'?visible.filter(p=>p.date.slice(0,10)>=stamp(days[0])&&p.date.slice(0,10)<=stamp(days[days.length-1])):monthPosts):visible;
 const reviewPosts=periodPosts.filter(p=>p.status==='En revisión');
