 const rangeDate=(d:string)=>new Date(d+'T12:00').toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'});
 const countPeriod=(dateFrom||dateTo)?(dateFrom&&dateTo?`${rangeDate(dateFrom)} – ${rangeDate(dateTo)}`:dateFrom?`Desde ${rangeDate(dateFrom)}`:`Hasta ${rangeDate(dateTo)}`):view==='Calendario'?(mode==='Semana'?`${fmt(stamp(days[0])+'T12:00')} – ${fmt(stamp(days[days.length-1])+'T12:00')}`:month.toLocaleDateString('es-ES',{month:'long',year:'numeric'})):'Todas las fechas';
 function move(step:number){setMonth(mode==='Semana'?new Date(month.getFullYear(),month.getMonth(),month.getDate()+step*7):new Date(month.getFullYear(),month.getMonth()+step,1));}
 function newPost(day?:string){dirty.current=false;if(!activeClients.length){setModal('client');setDraft({name:'',color:'#13DBFB',notes:''});return;}setSelected(null);setDraft({client_id:filter==='all'||!activeClients.some(c=>c.id===filter)?activeClients[0].id:filter,title:'',copy:'',channel:'Instagram',format:'Reel',date:`${day??stamp(new Date())}T10:00`,status:'Borrador',asset:''});setFormError('');setModal('post');}
 function open(p:any){dirty.current=false;setSelected(p);setComment('');setFormError('');}
 function edit(p:any){if(comment.trim()&&!confirm('Hay un comentario sin guardar. ¿Quieres descartarlo?'))return;setComment('');dirty.current=false;setDraft(p.status==='Publicado'?{...p,id:undefined,updated_at:undefined,status:'Borrador',title:p.title+' · nueva versión'}:{...p});setSelected(null);setFormError('');setModal('post');}
 function changeContentFormat(format:string,channel=draft.channel){const links=materialLinks(draft.asset??'');if(format!=='Carrusel'&&links.length>1&&!confirm('Al cambiar el tipo de contenido se conservará solo la primera imagen. ¿Quieres continuar?'))return;setDraft({...draft,channel,format,asset:format==='Carrusel'?draft.asset:(links[0]??'')});}
 async function save(e:React.FormEvent){e.preventDefault();const fresh=await mutate({action:modal==='post'?'post':modal==='client'?'client':'member',...draft},modal==='member'?'Acceso registrado. Ya puedes compartir el enlace':'Cambios guardados');if(fresh){dirty.current=false;setModal(null);}}
