 async function review(status:string){const fresh=await mutate({action:'review',id:selected.id,status,updated_at:selected.updated_at,body:comment},status==='Aprobado'?'Publicación aprobada':'Cambios solicitados');if(fresh){setSelected(fresh.posts.find((p:any)=>p.id===selected.id));setComment('');}}
